		LEIBNIZ_ASSERT(out != nullptr);		LEIBNIZ_ASSUME_ALIGNED(out, 32);

#if LEIBNIZ_COMPILER_MSVC
		for (size_t i = 0; i < N; i++)
			out[i] = inA[i] < inB[i] ? inB[i] : (inA[i] > inC[i] ? inC[i] : inA[i]);
#elif LEIBNIZ_COMPILER_CLANG || LEIBNIZ_COMPILER_GCC
		Utils::Unrolled::staticFor<0, N>([=](auto idx) {
			out[idx] = inA[idx.value] < inB[idx.value] ? inB[idx.value] : (inA[idx.value] > inC[idx.value] ? inC[idx.value] : inA[idx.value]);
										 });
#endif
